current.custom_css:
body:not(.template-index) .m-footer {
  border-top: 1px solid rgb(var(--color-border));
}

.m-button--link.m-button {
  --btn-link-border: 1px;
  line-height: 19px;
}

.m-custom-featured-slider .container-full {
  padding-left: 0;
  padding-right: 0;
}

.m-product-card__title .m-product-card__name {
  font-family: 'M-Body-Font';
  font-weight: 500;
}

.m-menu .m-menu__item .m-menu__link--main {
  font-size: 15px;
}

.m-custom-icon-box .m\:grid {
  align-items: center;
}

.m-custom-icon-box .m-icon-box__content h3 {
  font-family: 'M-Body-Font';
}

.m-custom-icon-box .m-icon-box__content .rte {
  margin-bottom: 15px;
}

.m-custom-hero .m-hero__content .m-hero__text {
  color: rgb(var(--color-body-text));
  margin-bottom: 40px;
  font-size: 18px;
}

.m-custom-slideshow .m-slide__content .m-slide__description {
  color: rgb(var(--color-body-text));
  margin-bottom: 40px;
  font-size: 18px;
}

.m-footer ul li a {
  text-transform: uppercase;
  font-weight: 500;
  font-size: 15px;
  line-height: 2.4;
}
.m-footer .m-footer--block-title {
  font-size: 20px !important;
}
@media (min-width: 1280px) {
  .m-footer .m-footer--block-inner {
    text-align: center;
  }

  .m-footer .m-footer--block-title {
    font-size: 34px !important;
    justify-content: center;
  }

  .m-custom-slideshow .m-slide__content .m-slide__title {
    font-size: 64px;
  }
}

@media (max-width: 767px) {
  .m-custom-featured-slider .m-section-py {
    padding: 40px 0;
  }

  .m-footer .m-footer--block-title {
    font-size: 18px;
  }

  .m-custom-hero .m-hero--content-stack {
    margin-bottom: 0;
  }
}
